            cpu->pc = 0x32F5u;
            if (nh_scpu_expect_next(cpu, 0x061997A8u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
            return nh_scpu_finish(cpu, bus, (7u) + ((cpu->d & 0x00FFu) != 0u ? 1u : 0u));
